import app from 'flarum/forum/app';
import RealtimeExtend from 'ext:flarum/realtime/forum/extenders/Realtime';
import applyCountedClick from './applyCountedClick';
export default function extendRealtime() {
  new RealtimeExtend().onBothChannelsEvent('linkClickCounted', raw => {
    applyCountedClick(raw, app.forum.attribute('linkClicksMinDisplay'));
  }).extend(app, {
    name: 'datlechin-link-clicks',
    exports: {}
  });
}